create extension if not exists pgcrypto;
create table if not exists admin_profiles (id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table if not exists customers (id uuid primary key default gen_random_uuid(), name text not null, phone text not null, email text, contact_preference text not null default 'whatsapp' check(contact_preference in ('whatsapp','phone','email')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists vehicles (id uuid primary key default gen_random_uuid(), customer_id uuid not null references customers on delete restrict, plate text not null, make text not null, model text not null, year int, color text, vin text, mileage int not null default 0 check(mileage>=0), created_at timestamptz not null default now(), unique(plate,customer_id), unique(id,customer_id));
create index if not exists vehicles_plate_idx on vehicles(plate);
create table if not exists work_orders (id uuid primary key default gen_random_uuid(), code text unique not null default ('OT-'||upper(substr(encode(gen_random_bytes(8),'hex'),1,10))), customer_id uuid not null references customers on delete restrict, vehicle_id uuid not null, concern text not null, status text not null default 'diagnostico' check(status in ('diagnostico','esperando_aprobacion','reparacion','esperando_repuesto','pausado','esperando_cliente','control_calidad','listo','entregado','cancelado')), block_reason text, qa_passed boolean not null default false, version int not null default 1, mileage int, eta_from timestamptz, eta_to timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
do $$ begin if not exists(select 1 from pg_constraint where conname='work_orders_vehicle_customer_fkey') then alter table work_orders add constraint work_orders_vehicle_customer_fkey foreign key(vehicle_id,customer_id) references vehicles(id,customer_id) on delete restrict; end if; end $$;
create index if not exists work_orders_status_updated_idx on work_orders(status,updated_at desc);
create table if not exists work_order_tasks (id uuid primary key default gen_random_uuid(), work_order_id uuid not null references work_orders on delete cascade, title text not null, weight int not null default 1 check(weight>0), completed_at timestamptz, visible_to_customer boolean not null default false, created_at timestamptz not null default now());
create table if not exists quotes (id uuid primary key default gen_random_uuid(), work_order_id uuid not null references work_orders on delete cascade, version int not null, currency char(3) not null default 'PEN' check(currency='PEN'), status text not null default 'pendiente' check(status in ('pendiente','aprobado','rechazado','vencido')), expires_at timestamptz, created_at timestamptz not null default now(), unique(work_order_id,version));
create table if not exists quote_lines (id uuid primary key default gen_random_uuid(), quote_id uuid not null references quotes on delete cascade, description text not null, kind text not null check(kind in ('trabajo','repuesto')), quantity numeric(10,2) not null check(quantity>0), unit_price numeric(12,2) not null check(unit_price>=0));
create table if not exists quote_decisions (id uuid primary key default gen_random_uuid(), quote_id uuid not null references quotes on delete restrict, decision text not null check(decision in ('aprobado','rechazado')), channel text not null check(channel in ('presencial','otp')), actor text not null, created_at timestamptz not null default now(), unique(quote_id));
create table if not exists part_requests (id uuid primary key default gen_random_uuid(), work_order_id uuid not null references work_orders on delete cascade, description text not null, urgency text not null default 'media' check(urgency in ('alta','media','baja')), provider text, resolution text check(resolution in ('cliente','taller')), status text not null default 'pendiente' check(status in ('pendiente','prometido','recibido','conforme','rechazado')), promised_at timestamptz, created_at timestamptz not null default now());
create table if not exists part_receipts (id uuid primary key default gen_random_uuid(), part_request_id uuid not null references part_requests on delete restrict, inspected_by uuid references auth.users, accepted boolean not null, note text, received_at timestamptz not null default now());
create table if not exists media_assets (id uuid primary key default gen_random_uuid(), work_order_id uuid not null references work_orders on delete cascade, storage_path text not null unique, category text not null check(category in ('ingreso','diagnostico','reparacion','control','entrega')), visible_to_customer boolean not null default false, caption text, created_at timestamptz not null default now());
create table if not exists work_order_events (id uuid primary key default gen_random_uuid(), work_order_id uuid not null references work_orders on delete cascade, event_type text not null, from_status text, to_status text, reason text, visible_to_customer boolean not null default false, actor text not null, created_at timestamptz not null default now());
create table if not exists access_grants (id uuid primary key default gen_random_uuid(), work_order_id uuid not null references work_orders on delete cascade, token_hash bytea unique not null, expires_at timestamptz not null, revoked_at timestamptz, created_at timestamptz not null default now());
create table if not exists notification_outbox (id uuid primary key default gen_random_uuid(), event_id uuid not null references work_order_events on delete cascade, channel text not null, payload jsonb not null, attempts int not null default 0, sent_at timestamptz, next_attempt_at timestamptz not null default now(), unique(event_id,channel));
create table if not exists audit_events (id uuid primary key default gen_random_uuid(), actor text not null, action text not null, entity_type text not null, entity_id uuid not null, details jsonb not null default '{}', created_at timestamptz not null default now());
create table if not exists eta_revisions (id uuid primary key default gen_random_uuid(), work_order_id uuid not null references work_orders on delete cascade, eta_from timestamptz, eta_to timestamptz, reason text not null, actor text not null, created_at timestamptz not null default now());
create table if not exists admin_sessions (token_hash bytea primary key, expires_at timestamptz not null, created_at timestamptz not null default now());
create table if not exists api_idempotency (idempotency_key uuid primary key, request_hash bytea not null, response jsonb, created_at timestamptz not null default now());

create or replace function reject_quote_line_change() returns trigger language plpgsql as $$ begin if exists(select 1 from quotes where id=coalesce(old.quote_id,new.quote_id) and status='aprobado') then raise exception 'Una cotización aprobada es inmutable'; end if; return coalesce(new,old); end $$;
drop trigger if exists quote_line_immutable on quote_lines;
create trigger quote_line_immutable before insert or update or delete on quote_lines for each row execute function reject_quote_line_change();
create or replace function reject_approved_quote_change() returns trigger language plpgsql as $$ begin if old.status='aprobado' then raise exception 'Una cotización aprobada es inmutable'; end if; if tg_op='DELETE' then return old; end if; return new; end $$;
drop trigger if exists approved_quote_immutable on quotes;
create trigger approved_quote_immutable before update or delete on quotes for each row execute function reject_approved_quote_change();
create or replace function reject_work_event_mutation() returns trigger language plpgsql as $$ begin raise exception 'work_order_events es append-only'; end $$;
drop trigger if exists work_event_immutable on work_order_events;
create trigger work_event_immutable before update or delete on work_order_events for each row execute function reject_work_event_mutation();
create or replace function reject_audit_mutation() returns trigger language plpgsql as $$ begin raise exception 'audit_events es append-only'; end $$;
drop trigger if exists audit_immutable on audit_events;
create trigger audit_immutable before update or delete on audit_events for each row execute function reject_audit_mutation();

create or replace function is_workshop_admin() returns boolean language sql stable security definer set search_path=public,auth as $$ select exists(select 1 from admin_profiles where id=auth.uid()) $$;
do $$ declare t text; begin foreach t in array array['admin_profiles','customers','vehicles','work_orders','work_order_tasks','quotes','quote_lines','quote_decisions','part_requests','part_receipts','media_assets','work_order_events','access_grants','notification_outbox','audit_events','eta_revisions','admin_sessions','api_idempotency'] loop execute format('alter table %I enable row level security',t); if t='admin_profiles' then execute 'drop policy if exists profile_self on admin_profiles';execute 'create policy profile_self on admin_profiles for select to authenticated using (id=auth.uid())'; elsif t not in ('admin_sessions','api_idempotency') then execute format('drop policy if exists admin_all on %I',t);execute format('create policy admin_all on %I for all to authenticated using (is_workshop_admin()) with check (is_workshop_admin())',t); end if; end loop; end $$;
grant select,insert,update,delete on admin_profiles,customers,vehicles,work_orders,work_order_tasks,quotes,quote_lines,quote_decisions,part_requests,part_receipts,media_assets,work_order_events,access_grants,notification_outbox,audit_events,eta_revisions to authenticated;
